    public Enemy(string name, int health)
    {
        Name = name;
        Health = health;
    }
}

Enemy dragon = new Enemy("Dragon", 250);

class Player
{
    public int Score { get; private set; }

    public void AddScore(int points)
    {
        Score += points;
    }

    public bool HasWon(int winningScore)
    {
        return Score >= winningScore;
    }
}

class ScoreTools
{
    public static int DoubleScore(int score)
    {
        return score * 2;
    }
}

int bonus = ScoreTools.DoubleScore(50);
Console.WriteLine(bonus);

class Character
{
    public string Name { get; }

    public Character(string name)
    {
        Name = name;
    }
}

class Mage : Character
{
    public int Mana { get; } = 100;

    public Mage(string name) : base(name) { }
}

interface IDamageable
{
    void TakeDamage(int amount);
}

class Enemy : IDamageable
{
    public int Health { get; private set; } = 100;

    public void TakeDamage(int amount)
    {
        Health = Math.Max(0, Health - amount);
    }
}

IDamageable target = new Enemy();
target.TakeDamage(25);

class Player
{
    public string Name { get; }
    public int Health { get; private set; } = 100;

    public Player(string name)
    {
